ulation", "children": [{"id": "2c563536-b908-4ac4-b7b5-ba1fec0ed26b", "type": "concept", "title": "presenting concern"}, {"id": "2885818c-9cfc-4d03-8e48-51831eb167c5", "type": "concept", "title": "trauma history"}, {"id": "7613b6a9-9e95-431e-abcc-196a3707d590", "type": "concept", "title": "risk factor"}, {"id": "b160c853-dc96-441c-83f1-ff4d3f794a75", "type": "concept", "title": "protective factor"}, {"id": "4656266c-82a3-44d1-a4b4-ea0fcbc62591", "type": "concept", "title": "biopsychosocial formulation"}, {"id": "da8edb77-d4fd-44ee-a105-c6d7769e48ae", "type": "concept", "title": "case hypothesis"}], "description": "Students synthesize trauma history, current needs, strengths, culture, and systems context."}, {"id": "a282f4d1-b1b2-4e27-af01-395f95853c58", "type": "subtopic", "title": "Practice Plan", "children": [{"id": "7c489896-9dfc-4548-bee8-22708c960b4b", "type": "concept", "title": "engagement strategy"}, {"id": "416fc0dd-80dd-4f6c-a864-7710911935b6", "type": "concept", "title": "safety plan"}, {"id": "8a3829d3-d98f-402f-9d8a-229c42cca4ac", "type": "concept", "title": "stabilization skill"}, {"id": "a99cb152-dbf4-416f-9795-51b74ed968d4", "type": "concept", "title": "treatment referral"}, {"id": "c8796547-f514-4c48-9b71-4ccb62f3fd16", "type": "concept", "title": "interdisciplinary collaboration"}, {"id": "ff6e6a54-7587-45c9-909f-e5a11442fbb5", "type": "concept", "title": "follow-up plan"}], "description": "A trauma-informed plan links engagement, safety, stabilization, referral, treatment, and collaboration."}, {"id": "e8c0c6af-9c0e-4759-bcd8-675e3fa42c25", "type": "subtopic", "title": "Documentation and Reflection", "children": [{"id": "89412db0-e82e-4643-bc31-60886f8100fd", "type": "concept", "title": "trauma-informed language"}, {"id": "c5b12c21-9009-4bd8-8877-47da58a40c8f", "type": "concept", "title": "objective observation"}, {"id": "c127596a-8a4c-408f-9b82-a39bbd89aa93", "type": "concept", "title": "client voice"}, {"id": "2379dfc5-29e8-4d1b-8ba4-853c7da5d2b