update public.learning_paths
set
  title = 'Trauma-Informed Practice',
  goal = 'Trauma-Informed Practice',
  summary = 'This syllabus is suitable for advanced undergraduate social work or graduate MSW students. It is practice-oriented while maintaining clear boundaries around scope, ethics, referral, and evidence-based treatment literacy.',
  data = $tripjson${"slug": "trauma-informed-practice", "title": "Trauma-Informed Practice", "description": "This syllabus is suitable for advanced undergraduate social work or graduate MSW students. It is practice-oriented while maintaining clear boundaries around scope, ethics, referral, and evidence-based treatment literacy.", "topics": [{"id": "5b723b95-c4f1-4912-b0a4-337d2000b431", "type": "topic", "title": "Trauma Definitions, Types, and Prevalence", "description": "This section develops trauma definitions, types, and prevalence through concrete concepts, practice moves, ethical checks, and trauma-informed applications.", "children": [{"id": "83d8cae0-d75e-42ec-8556-088f7f8de3c9", "type": "subtopic", "title": "Core Definitions", "children": [{"id": "7ef10498-82b4-489a-955e-df348e1144a9", "type": "concept", "title": "trauma"}, {"id": "5693f65e-33ab-409b-9a63-4e32bdc081cc", "type": "concept", "title": "traumatic event"}, {"id": "38cd74d2-b643-4f53-8cde-e3edf66c6d2f", "type": "concept", "title": "acute trauma"}, {"id": "42a7c29e-3dd6-4e86-a939-3c82bbb94b39", "type": "concept", "title": "chronic trauma"}, {"id": "71a92c1c-2b92-4855-ab91-31203e7fbb0c", "type": "concept", "title": "complex trauma"}, {"id": "e5ac6385-1dd7-4fcc-965f-6a30f0af265f", "type": "concept", "title": "developmental trauma"}, {"id": "b71f64f6-fdac-4f05-9bdb-0896a4623a2c", "type": "concept", "title": "collective trauma"}], "description": "Students need shared language before they can assess trauma impact or choose appropriate interventions."}, {"id": "b9925da7-93b9-4070-8e83-5b81eddd80ea", "type": "subtopic", "title": "Prevalence and Risk Contexts", "children": [{"id": "46df8987-3a82-4b63-80da-1680d651155a", "type": "concept", "title": "lifetime prevalence"}, {"id": "55670a4e-600d-435f-a179-c940256f0768", "type": "concept", "title": "interpersonal violence"}, {"id": "933256a1-f3db-4cca-8b62-1d3bdae9a5d1", "type": "concept", "title": "community violence"}, {"id": "95f1a56d-356e-4ab9-9d0b-b48d314f643f", "type": "concept", "title": "disaster exposure"}, {"id": "31309094-7695-4963-9fbd-4acab4966fa5", "type": "concept", "title": "medical trauma"}, {"id": "afeefbd9-7577-4cc0-986c-c3f454611388", "type": "concept", "title": "combat trauma"}, {"id": "6bb2d081-a550-4422-8b79-6188e2701073", "type": "concept", "title": "structural violence"}], "description": "Prevalence data helps students understand trauma as common, patterned, and socially distributed."}, {"id": "1f67b684-242a-416f-996a-89484f3e456e", "type": "subtopic", "title": "Trauma-Informed Versus Trauma-Specific", "children": [{"id": "c64a19ac-593a-4a6d-9242-5c02d38a0799", "type": "concept", "title": "trauma-informed approach"}, {"id": "3ac9ed3f-29b5-49c0-bcee-62d7c4af4c43", "type": "concept", "title": "trauma-specific intervention"}, {"id": "7b1ce725-a953-4377-9e1b-995059561b93", "type": "concept", "title": "universal precautions"}, {"id": "d3b7c043-8222-410b-b8f5-83e2156c5d58", "type": "concept", "title": "screening"}, {"id": "70795218-075b-47dd-93dd-31e1f60a23d3", "type": "concept", "title": "referral"}, {"id": "b9404a9e-e0d6-473c-8fba-07abe6cf6589", "type": "concept", "title": "scope of practice"}], "description": "This distinction prevents students from confusing universal practice principles with specialized clinical treatment."}]}, {"id": "6b514bbe-d075-4d8b-afc6-355dbc20b015", "type": "topic", "title": "Neurobiology of Trauma and the Stress Response", "description": "This section develops neurobiology of trauma and the stress response through concrete concepts, practice moves, ethical checks, and trauma-informed applications.", "children": [{"id": "b47e76ad-3d65-4d44-8031-3ff53e2b0d8f", "type": "subtopic", "title": "Threat Detection and Autonomic Response", "children": [{"id": "7491ba89-b026-4c5a-8f86-0b5e59eb835e", "type": "concept", "title": "amygdala"}, {"id": "d767d140-ae58-4e9c-a6e8-c0e0f93542b9", "type": "concept", "title": "prefrontal cortex"}, {"id": "3d186255-8b14-41b0-967a-0ae71f60fbb5", "type": "concept", "title": "hippocampus"}, {"id": "5608e975-95b9-42bf-9292-853dc21896a9", "type": "concept", "title": "sympathetic activation"}, {"id": "ebc9e049-5ce8-4696-92ff-004f10977eb7", "type": "concept", "title": "parasympathetic response"}, {"id": "97173b61-b790-4c0e-8468-3225ea9092b7", "type": "concept", "title": "fight-flight-freeze"}, {"id": "a36329e5-b367-443d-86f7-7e6cb704770c", "type": "concept", "title": "fawn response"}], "description": "This subtopic explains how the body prepares for survival and why trauma responses can persist."}, {"id": "b8b01409-bf2f-4b3a-85c1-436ee8657a20", "type": "subtopic", "title": "HPA Axis and Stress Hormones", "children": [{"id": "d5d4440f-ed92-4f11-8866-40f5a0ea92e9", "type": "concept", "title": "hypothalamus"}, {"id": "7b36a170-21bb-4508-a432-72000e3a78e2", "type": "concept", "title": "pituitary"}, {"id": "74613c2a-484b-4da3-8451-aa52bc268230", "type": "concept", "title": "adrenal glands"}, {"id": "6b1a232d-5eff-40d5-8d88-61fe64515400", "type": "concept", "title": "cortisol"}, {"id": "7a395c13-0b58-4662-82d3-e2ef3b87f9b4", "type": "concept", "title": "adrenaline"}, {"id": "5b7c7d07-b31a-491e-869c-4592d7d37d49", "type": "concept", "title": "allostatic load"}, {"id": "e99b9692-3441-4690-8d85-9f86407c3c1f", "type": "concept", "title": "toxic stress"}], "description": "Students learn how stress physiology affects sleep, attention, immune function, mood, and regulation."}, {"id": "dfda6d26-c997-4e41-927e-88fe32ab5b5a", "type": "subtopic", "title": "Memory, Dissociation, and Regulation", "children": [{"id": "03dfa72f-d7d3-415d-9bb3-90e0ee506994", "type": "concept", "title": "implicit memory"}, {"id": "27621901-577b-40b6-b0a3-08f9fa80abe5", "type": "concept", "title": "explicit memory"}, {"id": "04fb0148-cc33-4157-b830-1be66f7f3c40", "type": "concept", "title": "fragmented memory"}, {"id": "cd81a01d-cca9-4bcd-9f4c-13b3170c87b7", "type": "concept", "title": "dissociation"}, {"id": "ed4b4e6a-dfaf-4a77-bb5b-3111c5ca9f01", "type": "concept", "title": "grounding"}, {"id": "1a3017f1-ba20-4e18-8077-6512f58ba02b", "type": "concept", "title": "window of tolerance"}, {"id": "8ede0045-aace-4815-98c3-dc9bf983a466", "type": "concept", "title": "dual awareness"}], "description": "Trauma can shape memory and consciousness, so practitioners need careful, non-shaming explanations."}]}, {"id": "879d1f4f-f2f9-480f-b5c0-d7316eef3d95", "type": "topic", "title": "ACEs, Developmental Trauma, and Attachment", "description": "This section develops aces, developmental trauma, and attachment through concrete concepts, practice moves, ethical checks, and trauma-informed applications.", "children": [{"id": "e46bf529-0769-4181-b8f4-6f171ce34289", "type": "subtopic", "title": "Adverse Childhood Experiences", "children": [{"id": "9d2eafa7-ad6b-40c0-bd40-46f487bc9043", "type": "concept", "title": "ACE score"}, {"id": "dc46cb41-8130-4962-9416-28f043a30150", "type": "concept", "title": "household dysfunction"}, {"id": "2485e547-8d36-4fcb-8bda-4730788049d9", "type": "concept", "title": "abuse"}, {"id": "9bfb8d7b-8aca-4d40-93c4-8b583ce5bd83", "type": "concept", "title": "neglect"}, {"id": "7db7af8f-810e-49a0-a918-fc41a8111ffa", "type": "concept", "title": "dose-response relationship"}, {"id": "1a737834-1f1d-4f61-bb26-99c2924bc9cb", "type": "concept", "title": "protective factor"}], "description": "ACEs help students connect early adversity to later health, behavior, and social outcomes without determinism."}, {"id": "9259466d-f19b-4d8f-ac02-538b7fac7498", "type": "subtopic", "title": "Attachment and Relational Safety", "children": [{"id": "162e74b3-76e0-49ac-b875-fc17d8e69124", "type": "concept", "title": "secure attachment"}, {"id": "b1006895-9b06-496a-9978-c64e31074a69", "type": "concept", "title": "insecure attachment"}, {"id": "13dbcddd-c1ee-407e-a1c6-9bc116674f04", "type": "concept", "title": "disorganized attachment"}, {"id": "b32a50af-ba69-463d-943d-e27dbc8ec3cd", "type": "concept", "title": "attunement"}, {"id": "36702787-7888-45e8-8355-ce4502a9d22f", "type": "concept", "title": "co-regulation"}, {"id": "eb3ef510-2109-4a45-9d9d-8442cb756df3", "type": "concept", "title": "rupture and repair"}], "description": "Attachment concepts explain how caregiving relationships influence regulation, trust, and help-seeking."}, {"id": "393060f3-cbab-463b-b2b4-0fab84f4ff5a", "type": "subtopic", "title": "Developmental Timing", "children": [{"id": "359284cc-3d08-4848-868d-7f7692394e42", "type": "concept", "title": "sensitive period"}, {"id": "d9eaff26-6cd9-49f8-8def-238fab7f6831", "type": "concept", "title": "developmental task"}, {"id": "6ddde886-f9dd-4db2-85f1-e9e42ab16a97", "type": "concept", "title": "self-regulation"}, {"id": "8152fbc1-7e17-4918-b2c1-2e386959c5fe", "type": "concept", "title": "executive function"}, {"id": "6c2bb80e-fe59-4bde-8889-6af540ab20a5", "type": "concept", "title": "relational template"}, {"id": "1c8d712c-67a6-47a9-b25c-2abff27cf481", "type": "concept", "title": "developmental cascade"}], "description": "Students learn that the impact of trauma depends partly on when it occurs in development."}]}, {"id": "688e8164-a237-49dd-8590-d85b269a673b", "type": "topic", "title": "PTSD, Complex PTSD, and Trauma-Related Presentations", "description": "This section develops ptsd, complex ptsd, and trauma-related presentations through concrete concepts, practice moves, ethical checks, and trauma-informed applications.", "children": [{"id": "f032a1be-5045-4af5-99ef-7711b48e5f53", "type": "subtopic", "title": "PTSD Symptom Clusters", "children": [{"id": "0e986beb-9cb2-4778-8435-b5782439e521", "type": "concept", "title": "intrusion"}, {"id": "814a503f-fe0b-46ac-8fc3-78c25d852a9e", "type": "concept", "title": "avoidance"}, {"id": "bb7c3570-0751-414f-a7a3-d13f44aaff9d", "type": "concept", "title": "negative mood and cognition"}, {"id": "58d11e0d-63b4-4248-b6c1-d1ac89fd5009", "type": "concept", "title": "hyperarousal"}, {"id": "a6dfea3f-3359-4149-bcc3-e2d47ba180b3", "type": "concept", "title": "flashback"}, {"id": "a8d6d3d5-c05d-41e1-a925-1172ba2e6e23", "type": "concept", "title": "nightmare"}, {"id": "27f8c85d-56a8-4856-b55d-054daaa23ed1", "type": "concept", "title": "trigger"}], "description": "Students need symptom literacy to recognize when trauma-specific assessment or referral is needed."}, {"id": "d6443cc4-7250-4a6a-90e3-477c078e2e3b", "type": "subtopic", "title": "Complex Trauma Patterns", "children": [{"id": "6cedf50b-08be-420b-a484-8f7ef56e3392", "type": "concept", "title": "affect dysregulation"}, {"id": "994a3cc0-9692-41dc-8424-d9a0729eec78", "type": "concept", "title": "negative self-concept"}, {"id": "61633954-e003-4b98-ba10-49c5819c93f7", "type": "concept", "title": "interpersonal disturbance"}, {"id": "7a175dfa-110a-47ed-ad2d-63226830c89b", "type": "concept", "title": "shame"}, {"id": "d412f8c7-6bc1-4f11-9e60-0e89b8812cc9", "type": "concept", "title": "dissociation"}, {"id": "541f1b2e-95ba-48ff-a26a-9da7c22a25c5", "type": "concept", "title": "somatization"}], "description": "Complex trauma often involves relational, identity, affective, and somatic patterns beyond classic PTSD."}, {"id": "8021a6a8-f034-462c-a2b7-f6e925fcd565", "type": "subtopic", "title": "Co-Occurring Presentations", "children": [{"id": "fbacb87b-4690-4fb9-b4b4-73c4fe9e66d3", "type": "concept", "title": "depression"}, {"id": "e103988c-5fb5-4908-b082-9114c34a4ea6", "type": "concept", "title": "substance use"}, {"id": "74451ddc-6e6d-4eca-8bcd-ab12a7ad9386", "type": "concept", "title": "anxiety"}, {"id": "8876c32e-5d56-4f32-9bbc-4670a54ec323", "type": "concept", "title": "traumatic grief"}, {"id": "c25ed522-76c1-46ba-8a57-ed5096be9747", "type": "concept", "title": "self-harm"}, {"id": "84400497-f902-4474-9f58-ff93b133bd00", "type": "concept", "title": "sleep disturbance"}, {"id": "fad6aa37-927e-4b6f-9656-7df90b4b226a", "type": "concept", "title": "chronic pain"}], "description": "Trauma-informed practice requires seeing overlapping symptoms without reducing every problem to trauma alone."}]}, {"id": "fcf8f112-1d7b-481c-a16d-f98c300a04cb", "type": "topic", "title": "Trauma-Informed Care Principles", "description": "This section develops trauma-informed care principles through concrete concepts, practice moves, ethical checks, and trauma-informed applications.", "children": [{"id": "0c08f06a-5b9a-4400-a9c2-6af9d81b19ce", "type": "subtopic", "title": "Safety and Trustworthiness", "children": [{"id": "111975de-17c4-43cb-8f4a-33a31e9cbde6", "type": "concept", "title": "physical safety"}, {"id": "0edb4655-cb2c-421d-95c8-8aa049ac626b", "type": "concept", "title": "emotional safety"}, {"id": "bf61330a-e53e-4e63-a5ab-8e270c9f1a5d", "type": "concept", "title": "transparency"}, {"id": "73e41517-838a-4c07-a795-52ec7f95b245", "type": "concept", "title": "predictability"}, {"id": "c6068357-4581-4bf9-830f-ea0ba12bb5da", "type": "concept", "title": "clear boundaries"}, {"id": "f05a13af-a78b-400a-9091-6a3069f89841", "type": "concept", "title": "privacy"}], "description": "Safety and trust are the foundation for engagement, disclosure, and collaborative work."}, {"id": "17877286-33b4-4500-bf15-7bad33c6db99", "type": "subtopic", "title": "Choice, Collaboration, and Empowerment", "children": [{"id": "5cb4310e-eb76-4490-b0bf-8617cc07b974", "type": "concept", "title": "client autonomy"}, {"id": "3e439ff7-5f21-4104-bad5-7e7808dd1948", "type": "concept", "title": "shared decision-making"}, {"id": "31896a0b-6741-4de1-82a7-ab241ac0008a", "type": "concept", "title": "informed consent"}, {"id": "159dd073-fb95-4865-8592-810216861fd6", "type": "concept", "title": "strengths-based practice"}, {"id": "5b0cd6d6-4e1d-47a5-adef-872d28709143", "type": "concept", "title": "goal setting"}, {"id": "82b9aacc-4946-4b7f-bc8a-a1982993dba9", "type": "concept", "title": "choice points"}], "description": "Trauma-informed practice reduces coercion by giving clients voice and meaningful options."}, {"id": "ae3b1f14-fcd0-4dc0-a937-57c95d049111", "type": "subtopic", "title": "Peer Support, Culture, and Humility", "children": [{"id": "c6245bde-6539-4169-bc48-70737f33c4fd", "type": "concept", "title": "peer support"}, {"id": "9d1aa447-89a6-43b5-a0d2-74aa32a1a947", "type": "concept", "title": "cultural humility"}, {"id": "06d070b5-b96a-449e-8673-c1918458f474", "type": "concept", "title": "historical trauma"}, {"id": "f8dc5f0b-9463-4d8e-a475-6a78f2ba2259", "type": "concept", "title": "language access"}, {"id": "7a21f23d-c6bc-4784-b0be-7159581cc1f4", "type": "concept", "title": "anti-oppressive practice"}, {"id": "c69b151e-fd45-49b8-80f4-cd502441dac9", "type": "concept", "title": "belonging"}], "description": "Healing is relational and cultural, so practice must attend to identity, community, and power."}]}, {"id": "2a72ffaf-aa1a-4bd5-9a85-59258bb3f9f8", "type": "topic", "title": "Engagement, Screening, Assessment, and Stabilization", "description": "This section develops engagement, screening, assessment, and stabilization through concrete concepts, practice moves, ethical checks, and trauma-informed applications.", "children": [{"id": "3a0f1e25-b975-4404-b9d6-ccdef56218e8", "type": "subtopic", "title": "Engagement and Consent", "children": [{"id": "3b1d65c4-b5f7-4d03-acf5-d1d10977cecb", "type": "concept", "title": "warm handoff"}, {"id": "ea0ac651-cb81-48c3-8d28-0a2b8fa74e45", "type": "concept", "title": "rapport"}, {"id": "7c18c85a-6967-44f1-b9a2-860e8a89ae4a", "type": "concept", "title": "informed consent"}, {"id": "e83218d5-ed5d-4cbf-84c4-a91ac91e59b3", "type": "concept", "title": "permission-seeking"}, {"id": "7e113388-ae90-4bd3-9477-5344a8a2db92", "type": "concept", "title": "choice of pace"}, {"id": "c8e89d5f-bb78-46de-9cd5-d266ba933791", "type": "concept", "title": "explain the why"}], "description": "Students learn to build rapport without pressuring disclosure or reenacting control."}, {"id": "c44984d3-3fc4-46a6-aed6-373af2600cc3", "type": "subtopic", "title": "Screening and Assessment", "children": [{"id": "3e22f446-21a8-465e-886b-71acc0285c42", "type": "concept", "title": "trauma screen"}, {"id": "a399f354-477a-48df-833d-1f9d0deb5a78", "type": "concept", "title": "PTSD checklist"}, {"id": "bb4b900f-4751-4222-9a62-92182febcfd3", "type": "concept", "title": "risk assessment"}, {"id": "e18ad12f-e7a0-4609-9a35-0d683a058620", "type": "concept", "title": "strengths assessment"}, {"id": "ac402c27-ac56-4c1e-83d3-a0aebd07a9d7", "type": "concept", "title": "clinical interview"}, {"id": "e1dcfc1c-602f-45bc-95db-16e6537be463", "type": "concept", "title": "referral threshold"}], "description": "Screening helps identify needs, but it must be purposeful, safe, and connected to action."}, {"id": "b17d4017-e062-444e-abcc-590d51a4f57b", "type": "subtopic", "title": "Stabilization Skills", "children": [{"id": "57cddb19-84bf-4412-8ce1-48353981d262", "type": "concept", "title": "grounding"}, {"id": "f544f5e8-2d71-46ff-ac23-351d28b68bef", "type": "concept", "title": "breathing"}, {"id": "1cbeb825-8ec3-4e5c-bc68-34db6755f697", "type": "concept", "title": "orienting"}, {"id": "220d561d-ebcd-461f-b67f-d3e50adfa229", "type": "concept", "title": "safety planning"}, {"id": "f029c721-3a1d-4c9e-ab47-c3a24da7a540", "type": "concept", "title": "coping card"}, {"id": "849c587a-a6df-4a03-8407-acc1194510eb", "type": "concept", "title": "distress tolerance"}], "description": "Stabilization helps clients stay present and safe before deeper trauma processing."}]}, {"id": "aaf0b540-5008-40ad-8fc0-7c7892395b46", "type": "topic", "title": "Evidence-Based Trauma Treatments: TF-CBT, CPT, PE, and Narrative Approaches", "description": "This section develops evidence-based trauma treatments: tf-cbt, cpt, pe, and narrative approaches through concrete concepts, practice moves, ethical checks, and trauma-informed applications.", "children": [{"id": "4c2287c4-3336-4625-8f69-d92262a973d2", "type": "subtopic", "title": "Cognitive and Exposure-Based Models", "children": [{"id": "a195eb12-110f-4d02-92e9-e6de6b539311", "type": "concept", "title": "CPT"}, {"id": "65b943ba-8824-4a98-bbeb-1bf1455186a0", "type": "concept", "title": "Prolonged Exposure"}, {"id": "500c5289-745b-419c-a3cc-5ca29f25fe8e", "type": "concept", "title": "stuck point"}, {"id": "d020f352-4445-4cde-ac61-e7d003ac9e38", "type": "concept", "title": "avoidance hierarchy"}, {"id": "e97afc2c-e4e6-4fec-8a68-45bc5c495f19", "type": "concept", "title": "imaginal exposure"}, {"id": "b4441f03-1e70-4d1b-b384-19c662aa1ee4", "type": "concept", "title": "in vivo exposure"}], "description": "Students learn the mechanisms behind well-supported trauma treatments without overstepping scope."}, {"id": "54d430ac-ddb3-4424-94e0-e1a28bb9911b", "type": "subtopic", "title": "Child and Family Trauma Treatments", "children": [{"id": "9baef8f2-549b-4222-b64a-ca5078b2b466", "type": "concept", "title": "TF-CBT"}, {"id": "0f540a1b-7328-4259-9669-5db43b530dd8", "type": "concept", "title": "PRACTICE components"}, {"id": "244e12af-9af6-4a3e-b80f-b73eddd3175f", "type": "concept", "title": "psychoeducation"}, {"id": "1e0591b7-a67d-4801-af03-399bd6d3df64", "type": "concept", "title": "affective modulation"}, {"id": "e7a997a8-f9b8-4ea4-a985-1f4f16c2ea24", "type": "concept", "title": "trauma narrative"}, {"id": "978dfa8a-836d-4605-b045-fd69e9ed5102", "type": "concept", "title": "caregiver involvement"}], "description": "Child trauma work often includes caregivers, developmentally appropriate skills, and family safety."}, {"id": "923e730b-0393-4584-892f-fa30cae39a77", "type": "subtopic", "title": "Narrative and Meaning-Making", "children": [{"id": "7b9902ad-ab65-4333-9c0b-6a1db6309851", "type": "concept", "title": "trauma narrative"}, {"id": "486baeb1-c5d9-44f2-bc16-308c5401493e", "type": "concept", "title": "testimony"}, {"id": "5dd2910a-4a84-4cb9-bca9-104071a17427", "type": "concept", "title": "meaning-making"}, {"id": "c800f807-ba68-4719-849e-544782b5dfb1", "type": "concept", "title": "externalization"}, {"id": "5f36fa2e-6872-4ff0-827e-24c960e88a0a", "type": "concept", "title": "life story"}, {"id": "01be2f2f-dc42-4db4-a802-565e0de0deef", "type": "concept", "title": "remembrance and mourning"}], "description": "Narrative approaches help organize memory, restore agency, and connect trauma to meaning and identity."}]}, {"id": "8f9fe8ea-c5ac-46b2-965f-748afe1eec74", "type": "topic", "title": "EMDR, Somatic, Mindfulness, and Body-Based Approaches", "description": "This section develops emdr, somatic, mindfulness, and body-based approaches through concrete concepts, practice moves, ethical checks, and trauma-informed applications.", "children": [{"id": "096c0ba0-7260-4156-96d2-599018ac07cb", "type": "subtopic", "title": "EMDR and Memory Processing", "children": [{"id": "04931b62-69f5-44e8-9efe-8c9e0aeda026", "type": "concept", "title": "EMDR"}, {"id": "86dd718f-87ac-4ecc-a8a7-df6bb251a2f0", "type": "concept", "title": "bilateral stimulation"}, {"id": "83db4afc-d5b8-425e-bee2-119a33a69dac", "type": "concept", "title": "target memory"}, {"id": "41842499-9383-470c-b889-20e31b60f886", "type": "concept", "title": "negative cognition"}, {"id": "8a95796a-2a94-47c2-bfc6-08ff029109c6", "type": "concept", "title": "resource installation"}, {"id": "1ef94aa4-ba3d-4333-ba64-e519867377a8", "type": "concept", "title": "fidelity"}], "description": "Students learn what EMDR is, where it fits, and why training and scope matter."}, {"id": "54400ae2-d95e-4397-b89b-9e33afcf539b", "type": "subtopic", "title": "Somatic and Regulation Approaches", "children": [{"id": "99ee5729-dcea-4d4a-95a3-4ceae0294945", "type": "concept", "title": "somatic awareness"}, {"id": "5b852390-e3d4-429f-9f3d-233c34e75a6e", "type": "concept", "title": "interoception"}, {"id": "cc8a948c-f7af-4c52-ba5f-634dde51bbbf", "type": "concept", "title": "pendulation"}, {"id": "2b02338e-4692-43f0-9a46-054f1b0a5a36", "type": "concept", "title": "titration"}, {"id": "ab8e2ab4-9e81-468a-a64f-a13c845d9272", "type": "concept", "title": "grounding through senses"}, {"id": "b3eeb77e-e6d9-46e6-a3cd-9f79d85550a4", "type": "concept", "title": "body boundary"}], "description": "Body-based approaches address arousal, sensation, and regulation as part of trauma recovery."}, {"id": "f9124bc2-8fae-4909-8e3b-43adfbd4788e", "type": "subtopic", "title": "Mindfulness and Stabilization", "children": [{"id": "37e8e88c-85de-45ba-b322-b38bef5c38a6", "type": "concept", "title": "present-moment awareness"}, {"id": "87c3b19b-7504-4f2b-b5bd-3d4f5b33ee40", "type": "concept", "title": "choice of focus"}, {"id": "ce54d84d-8bcd-4ce0-89b3-d3071086474b", "type": "concept", "title": "eyes open option"}, {"id": "127f7eb5-f149-4009-9de8-199d9daa7086", "type": "concept", "title": "anchoring"}, {"id": "8dcd2bf0-fcc9-42e6-b3f4-de711fb7fbc9", "type": "concept", "title": "self-compassion"}, {"id": "daa2f75e-2694-41cd-a996-caf18d86e0f8", "type": "concept", "title": "trauma-sensitive mindfulness"}], "description": "Mindfulness can support regulation, but trauma-sensitive adaptation is essential."}]}, {"id": "3cab3021-e66a-4a2d-9c67-02ff20ad6c53", "type": "topic", "title": "Trauma Across the Lifespan and in Specific Populations", "description": "This section develops trauma across the lifespan and in specific populations through concrete concepts, practice moves, ethical checks, and trauma-informed applications.", "children": [{"id": "c7a4890f-161b-4d73-a192-34bd8c22c063", "type": "subtopic", "title": "Children and Adolescents", "children": [{"id": "63b881ea-ebe8-42f6-ace6-7e386d0c27af", "type": "concept", "title": "play behavior"}, {"id": "e9701508-5f34-4741-8b5f-8409401555f9", "type": "concept", "title": "regression"}, {"id": "744b7943-f5dd-4c1f-816c-1192eda09fec", "type": "concept", "title": "school functioning"}, {"id": "3c9f337b-ffab-4446-9ba6-fc179ce13cde", "type": "concept", "title": "caregiver support"}, {"id": "87011b84-3699-4a43-899f-5fe1212d456b", "type": "concept", "title": "developmental assessment"}, {"id": "4fefdb88-3210-469a-a926-b1b0e682e1d7", "type": "concept", "title": "mandated reporting"}], "description": "Developmental stage shapes symptoms, communication, caregiver involvement, and treatment planning."}, {"id": "8201dfb3-d742-4d2c-a79f-f9b598c2a350", "type": "subtopic", "title": "Adults and Older Adults", "children": [{"id": "fc932423-9547-4a4f-87ed-92bdf4ed92a4", "type": "concept", "title": "intimate partner violence"}, {"id": "93db4d56-1cc1-4f81-bf78-54c4bb17282b", "type": "concept", "title": "workplace trauma"}, {"id": "63bebd5c-93fc-427a-89f0-7afa3ce51c66", "type": "concept", "title": "medical trauma"}, {"id": "87ad7a01-d5f5-4549-95e3-86148b2cbaa3", "type": "concept", "title": "elder abuse"}, {"id": "b7cd9972-ffeb-4cb6-99e2-cdb6e4786c16", "type": "concept", "title": "bereavement"}, {"id": "b4ef8412-5bc4-4589-948e-ede86e9d8b4d", "type": "concept", "title": "functional impairment"}], "description": "Adult trauma practice may include cumulative adversity, health effects, grief, caregiving, and aging-related vulnerability."}, {"id": "6c1f65fe-ef22-40dd-8dbf-33f27ec03c4e", "type": "subtopic", "title": "Population-Specific Adaptation", "children": [{"id": "b7f34dc8-3ee8-41b1-a284-5b0ca7510310", "type": "concept", "title": "veterans"}, {"id": "40c63c06-c6c4-4c9a-a43f-a37348dd84b0", "type": "concept", "title": "refugees"}, {"id": "78068750-eaea-4c48-88b1-63f637b75854", "type": "concept", "title": "LGBTQ+ survivors"}, {"id": "aeb3f4b4-77b0-45e5-80ba-70d3888fd235", "type": "concept", "title": "people with disabilities"}, {"id": "b08505cd-8bb8-4aed-88de-fcc562dc4ae1", "type": "concept", "title": "survivors of trafficking"}, {"id": "0c6a0095-f8c9-4fc8-8766-355483f331f6", "type": "concept", "title": "rural communities"}], "description": "Students learn to adapt practice for identity, context, access, and community resources."}]}, {"id": "a1575345-b158-4265-b36f-215f22e5c4a4", "type": "topic", "title": "Community, Historical, Racial, and Collective Trauma", "description": "This section develops community, historical, racial, and collective trauma through concrete concepts, practice moves, ethical checks, and trauma-informed applications.", "children": [{"id": "7b8cb5c6-4493-464c-9055-1b9895a7eb4a", "type": "subtopic", "title": "Historical and Racial Trauma", "children": [{"id": "19d957ee-f997-4cd6-9887-44c07dc32856", "type": "concept", "title": "historical trauma"}, {"id": "66b823d7-f3f8-42cc-a3f8-458068a29df3", "type": "concept", "title": "racial trauma"}, {"id": "52c5eeee-8d4b-41e5-b9fe-cb61a0172586", "type": "concept", "title": "colonization"}, {"id": "c7dbfbf4-1c04-41c0-bfef-91d04e43a10d", "type": "concept", "title": "forced displacement"}, {"id": "9e5771c1-6c0d-4ed6-96ad-ebb7d08e44f4", "type": "concept", "title": "intergenerational trauma"}, {"id": "d9146ca2-b8bb-421c-891f-371b32f2b858", "type": "concept", "title": "microaggression"}], "description": "This subtopic connects individual distress to collective histories and ongoing systems of harm."}, {"id": "1da5ef2f-3135-46d8-91de-f2f7d6307be0", "type": "subtopic", "title": "Community Violence and Disaster", "children": [{"id": "6d08dfbb-c893-4fb1-a14d-2f66957faa90", "type": "concept", "title": "community violence"}, {"id": "3da3ee8e-3b6f-4202-a5ca-08702aa76204", "type": "concept", "title": "mass violence"}, {"id": "8884305f-59ac-4478-a9b4-482df9d4f94a", "type": "concept", "title": "natural disaster"}, {"id": "ab573e2d-d20e-4697-8439-9d113be7794d", "type": "concept", "title": "collective grief"}, {"id": "18dd0c09-627c-4aea-919d-a29b02d55d0d", "type": "concept", "title": "mutual aid"}, {"id": "871cf767-b112-4f49-9daf-787aeabe6d3b", "type": "concept", "title": "community resilience"}], "description": "Community-level trauma requires attention to safety, resources, collective grief, and recovery infrastructure."}, {"id": "95a884e6-023f-4611-a825-68a97c6b66c0", "type": "subtopic", "title": "Anti-Oppressive Trauma Practice", "children": [{"id": "54e2cf68-7f2a-487c-b3ce-f95685512dc2", "type": "concept", "title": "structural racism"}, {"id": "93bf07d7-ad83-4d31-9160-28e3270fca3b", "type": "concept", "title": "poverty"}, {"id": "39f5de33-937d-4488-9edb-46327d60d3ff", "type": "concept", "title": "policy violence"}, {"id": "fa56abf7-1de1-4814-862f-d5573e833ae4", "type": "concept", "title": "cultural protective factors"}, {"id": "25087ff3-a39d-4957-b54c-85f0daec2cf6", "type": "concept", "title": "community healing"}, {"id": "339dbbaa-630f-4775-ac69-de7eab0fd0d3", "type": "concept", "title": "liberation practice"}], "description": "Students learn to avoid pathologizing communities and instead analyze power, context, and resistance."}]}, {"id": "702d29bf-830c-4ce7-85fd-6481e6936ce9", "type": "topic", "title": "Trauma-Informed Organizations and Systems Change", "description": "This section develops trauma-informed organizations and systems change through concrete concepts, practice moves, ethical checks, and trauma-informed applications.", "children": [{"id": "216e7021-cd39-4273-8c3c-cc70031abe1b", "type": "subtopic", "title": "Organizational Principles", "children": [{"id": "bd936dc8-fcf7-432c-8707-3170b83f3e2b", "type": "concept", "title": "leadership commitment"}, {"id": "3db0d9bd-b0f2-4cca-aa85-eb91be0f8dc2", "type": "concept", "title": "policy review"}, {"id": "22f4db52-442a-45d7-9ae9-9924fd1afd77", "type": "concept", "title": "staff training"}, {"id": "e15e58dc-6043-4442-bb49-87f53a73201c", "type": "concept", "title": "client voice"}, {"id": "a8c90407-e425-4958-8b55-404979597ad6", "type": "concept", "title": "environmental safety"}, {"id": "af1831a2-3429-4c1a-a785-a14a50577cc2", "type": "concept", "title": "feedback loops"}], "description": "Trauma-informed care must be embedded in systems, not only individual provider behavior."}, {"id": "4b32e0d2-77c6-441f-823f-5f2afd02ebe1", "type": "subtopic", "title": "Practice Environment and Workflow", "children": [{"id": "6951f352-4794-4703-99db-334079fcea83", "type": "concept", "title": "welcoming environment"}, {"id": "102d0829-d8db-491d-bee5-bcec17789b52", "type": "concept", "ti