"id": "dc2e45f4-63bf-4a26-860d-ab3a18122eba", "type": "concept", "title": "compassion fatigue"}, {"id": "07225222-7b84-4a87-8124-262505e5e5e8", "type": "concept", "title": "burnout"}, {"id": "82aed08d-cfd1-4561-abea-252fc4136d68", "type": "concept", "title": "moral distress"}, {"id": "1f37b89c-cca8-4621-b9b4-755d73b7c518", "type": "concept", "title": "countertransference"}], "description": "Helpers can be affected by exposure to others' trauma, so recognition is an ethical practice issue."}, {"id": "60f4044b-c523-4416-8a5b-a97b05b2d7f6", "type": "subtopic", "title": "Supervision and Boundaries", "children": [{"id": "90855631-76e5-4939-9a33-cb4b48d52a50", "type": "concept", "title": "reflective supervision"}, {"id": "89459cb5-61a3-471f-b46d-44a953e2dfe4", "type": "concept", "title": "consultation"}, {"id": "ca87e325-59c2-4e89-a209-4305c1e74bff", "type": "concept", "title": "caseload balance"}, {"id": "2c3c119a-aed8-46d1-9242-e1a9e0eaac08", "type": "concept", "title": "boundary setting"}, {"id": "2933fab2-f825-4021-849d-47357890ef23", "type": "concept", "title": "debriefing"}, {"id": "01f406cd-8679-45c6-802a-a9f5cc7faea0", "type": "concept", "title": "ethical self-monitoring"}], "description": "Supervision and boundaries help sustain practice and protect client care."}, {"id": "96d0d55f-c373-4bc7-9cb4-14edb1360422", "type": "subtopic", "title": "Sustainable Practice", "children": [{"id": "de32002e-71dd-4548-be81-d361d3d3d403", "type": "concept", "title": "trauma stewardship"}, {"id": "e9f939ff-efe3-4746-b899-0576cca516ad", "type": "concept", "title": "self-care plan"}, {"id": "00cb200b-46dd-47a4-b82d-4e08b8ac65f7", "type": "concept", "title": "collective care"}, {"id": "0a9fc99c-411a-431f-9c15-72ce92b89221", "type": "concept", "title": "restorative practice"}, {"id": "e4daf55e-e376-49a8-bf31-bfe207c4e057", "type": "concept", "title": "peer support"}, {"id": "ac463c8a-84ae-47b9-b607-947f122a5dce", "type": "concept", "title": "wellness accountability"}], "description": "Students build a realistic sustainability plan grounded in agency and community supports."}]}, {"id": "d8557935-35f4-464e-9f38-e8345a8cd2f6", "type": "topic", "title": "Resilience, Post-Traumatic Growth, and Strengths-Based Practice", "description": "This section develops resilience, post-traumatic growth, and strengths-based practice through concrete concepts, practice moves, ethical checks, and trauma-informed applications.", "children": [{"id": "edeab197-28d6-402a-b61f-b1e2c94df297", "type": "subtopic", "title": "Resilience and Protective Factors", "children": [{"id": "76dcb4bc-a145-4365-bef2-cde478edad9d", "type": "concept", "title": "resilience"}, {"id": "0cb7849e-0030-410b-8d8e-d4da6b72b7e9", "type": "concept", "title": "protective factor"}, {"id": "342b46fe-3f1d-4d9b-98f9-ed9c480e2539", "type": "concept", "title": "social support"}, {"id": "5486e221-577c-4402-8eb0-210c1a5349dc", "type": "concept", "title": "cultural identity"}, {"id": "416faca9-9087-4c36-a028-3647fe9c2fb7", "type": "concept", "title": "spirituality"}, {"id": "0894bd7a-1d1b-440d-b7fc-a68a355173b3", "type": "concept", "title": "adaptive coping"}], "description": "Students learn to identify strengths without minimizing harm."}, {"id": "701c22bd-66a3-405b-8835-b007c660c5b3", "type": "subtopic", "title": "Post-Traumatic Growth", "children": [{"id": "c889d323-e504-4417-a0c7-21f407957585", "type": "concept", "title": "post-traumatic growth"}, {"id": "8437a022-e33b-450c-8104-036184a18768", "type": "concept", "title": "meaning-making"}, {"id": "88c654e1-0d11-41b5-aa25-4fcf6d9c0649", "type": "concept", "title": "agency"}, {"id": "556154c3-df6f-4b1a-ba22-4ed846ebc074", "type": "concept", "title": "hope"}, {"id": "f91984c8-9636-4119-a1c8-c10f03e28674", "type": "concept", "title": "values clarification"}, {"id": "72b63558-96c2-45da-9c02-2515ec6c3a52", "type": "concept", "title": "narrative reconstruction"}], "description": "Growth is not required of survivors, but some clients find meaning, priorities, o